/bin/bash -lc "python3 - <<'PY'
import zipfile, xml.etree.ElementTree as ET
path='/home/user/Desktop/Course Timetable.xlsx'
ns='{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
with zipfile.ZipFile(path) as z:
    root=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    print('dimension', root.find(ns+'dimension').attrib)
    cols=root.find(ns+'cols')
    if cols is not None:
        for col in cols: print('col', col.attrib)
    sd=root.find(ns+'sheetData')
    for row in sd.findall(ns+'row'):
        print('row', row.attrib)
        for c in row.findall(ns+'c'):
            print('  c', c.attrib, [child.tag.split('}')[-1]+':'+(child.text or '') for child in c])
    mc=root.find(ns+'mergeCells')
    if mc is not None:
        print('mergeCells', mc.attrib)
        for m in mc: print(m.attrib)
PY"

